evals.prompt:
Convert the following JSONPath states to JSONata mode and explain the common pitfalls to avoid (especially why filtering an array directly in a `Map` state's `Items` field like `"Items": "{% $states.input.orders[status = 'pending'] %}"` can randomly fail when 0 or 1 orders match):
```json
{
  "StartAt": "CheckCustomer",
  "States": {
    "CheckCustomer": {
      "Type": "Choice",
      "Choices": [
        {
          "And": [
            { "Variable": "$.priority", "StringEquals": "high" },
            { "Variable": "$.age", "NumericLessThanEquals": 30 }
          ],
          "Next": "ProcessPendingOrders"
        },
        { "Not": { "Variable": "$.email", "IsPresent": true }, "Next": "MissingEmail" }
      ],
      "Default": "StandardFlow"
    },
    "ProcessPendingOrders": {
      "Type": "Map",
      "ItemsPath": "$.orders",
      "Parameters": {
        "orderItem.$": "$$.Map.Item.Value",
        "itemIndex.$": "$$.Map.Item.Index"
      },
      "Iterator": {
        "StartAt": "InvokeWorker",
        "States": {
          "InvokeWorker": {
            "Type": "Task",
            "Resource": "arn:aws:states:::lambda:invoke",
            "Parameters": {
              "FunctionName": "arn:aws:lambda:ap-south-1:123456789012:function:Worker:$LATEST",
              "Payload.$": "$"
            },
            "ResultSelector": { "workerId.$": "$.Payload.id" },
            "ResultPath": "$.workerOut",
            "OutputPath": "$.workerOut",
            "End": true
          }
        }
      },
      "ResultPath": "$.processedOrders",
      "End": true
    }
  }
}
```
